"""Trusted test adapter for the opt-in detached supervisor acceptance case."""
import json
import os
from pathlib import Path
import time

from agent_runtime.core import ArtifactHandler, Outcome
from agent_runtime.task_manifest import atomic_json


def build(root, store, run_id):
    root = Path(root)
    def observe(kind, task):
        row = dict(kind=kind, task=task, pid=os.getpid(), at=time.time())
        with (root / 'actions.jsonl').open('a', encoding='utf-8') as stream:
            stream.write(json.dumps(row) + '\n')

    class Handler(ArtifactHandler):
        def run(self, task, context):
            task_id = task['task_id']
            observe('handler_start', task_id)
            if task_id == 'A' and not (root / 'retry.marker').exists():
                (root / 'retry.marker').touch(exist_ok=False)
                observe('input_unavailable', task_id)
                return Outcome('retry', 'fixture input unavailable on first delivery')
            content = b'validated payload' if task_id == 'A' else (root / 'A.bin').read_bytes() + b' consumed'
            target = root / (task_id + '.bin')
            if not target.exists():
                with target.open('xb') as stream:
                    stream.write(content)
                observe('payload_created', task_id)
            atomic_json(root / task['report_path'], dict(task_id=task_id, summary='verified fixture',
                        data=[dict(kind='synthetic', description='generated bytes checked by digest')]))
            return super().run(task, context)

    def maintain(report):
        marker = root / 'restart.marker'
        if store.snapshot(run_id)['state']['tasks']['A']['status'] == 'done' and not marker.exists():
            marker.touch(exist_ok=False)
            observe('injected_exit_after_A', 'A')
            os._exit(72)

    handler = Handler(root)
    return dict(handlers={'fixture': handler}, authorize=lambda plan, task, candidate: candidate is handler,
                maintain=maintain)
